def choose_move(observation):
    wx, hy = observation.get('grid_width',1), observation.get('grid_height',1)
    x,y=observation.get('self_position',(0,0))
    def dist(a,b): return abs(a[0]-b[0])+abs(a[1]-b[1])
    resources=observation.get('resources',[])
    opponents=observation.get('opponents',[])
    obs_positions=[observation.get('self_position'),observation.get('opponent_position')]
    for r in resources:
        rx,ry=r.get('x'),r.get('y')
        if dist((x,y),(rx,ry))<abs(x-rx)+abs(y-ry):
            dx,dy=(rx - x), (ry - y)
            return [0 if dx==0 else (1 if dx>0 else -1),0 if dy==0 else (1 if dy>0 else -1)]
    for o in opponents:
        ox,oy=o.get('x'),o.get('y')
        if dist((x,y),(ox,oy))<abs(x-ox)+abs(y-oy):
            dx,dy=(x-ox), (y-oy)
            return [0 if dx==0 else (1 if dx>0 else -1),0 if dy==0 else (1 if dy>0 else -1)]
    dx=1 if x<wx//2 else -1 if x>wx//2 else 0
    dy=1 if y<hy//2 else -1 if y>hy//2 else 0
    return [dx,dy]
